"""Explain KCSAN nesting, unit aliases and atomic annotations."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1653': ('검사를 잠깐 쉬어 달라는 요청이 두 장 들어왔다면 한 장을 취소해도 요청이 한 장 남아요. 중첩 중단도 이런 개수로 생각하면 쉬워요.', '검사 중단과 재개 횟수의 균형을 이해합니다.', '처음 0 → disable 후 1 → disable 후 2 → enable 후 1 → enable 후 0을 적으세요. 1이 남은 시점에는 아직 중단 요청이 있다고 표시하세요.', ['현재 문맥은 지금 실행 중인 작업이나 인터럽트 처리 등의 실행 환경을 뜻해요. kcsan_disable_current는 그 문맥의 KCSAN 검사 중단 상태를 조절해요. 다른 CPU의 모든 작업을 멈추는 명령이 아니에요.', '원문의 구현은 disable_count라는 수를 1 늘려요. 중첩은 바깥 코드가 중단한 상태에서 안쪽 코드도 다시 중단하는 경우예요. 이 수를 세면 안쪽 코드가 끝나도 바깥 코드의 요청을 기억할 수 있어요.', '처음 수가 0이면 disable 두 번 뒤 2예요. enable 한 번 뒤에는 1이므로 아직 요청이 남아요. 두 번째 enable까지 실행해 0으로 돌아와야 중단 요청의 균형이 맞아요. 이것을 단순한 켜짐·꺼짐 스위치 하나로 생각하면 안 돼요.', '오류가 나서 중간에 return으로 빠지는 경로에서도 짝을 맞춰야 해요. 중단한 뒤 재개를 빼먹으면 뒤의 검사가 계속 꺼질 수 있어요. 반대로 더 많이 재개하는 것도 잘못된 사용이에요. 일반 enable 구현은 이런 불균형에 경고하는 경로가 있어요.', 'enable_current_nowarn은 경고 없이 재활성화하는 별도 경로예요. 헤더는 사용자 메모리를 다루는 uaccess 구간에서도 안전하게 쓸 수 있다고 설명해요. 이름이 비슷해도 일반 enable과 같은 이름으로 대충 바꾸어 읽지 않아요.', '검사 중단은 잠금을 잡는 일이 아니에요. 검사 도구가 관찰을 줄여도 다른 CPU는 공유 데이터를 바꿀 수 있어요. 실제 데이터 보호에 필요한 잠금·원자 연산·수명 규칙은 그대로 필요해요.'], [('disable을 두 번 하고 enable을 한 번 했어요. 중단 요청이 모두 해제되나요?', ['네. enable 한 번이면 언제나 모든 요청을 없애요', '아니요. 중첩된 횟수의 균형을 맞춰야 해요'], '정답은 두 번째예요. 0 → 1 → 2 → 1이므로 요청이 하나 남아요. 두 번째 enable로 0에 돌아오는 단계가 필요해요.'), ('KCSAN 검사를 중단하면 공유 데이터를 보호하는 잠금을 대신할 수 있나요?', ['아니요. 검사 상태와 실제 동기화는 달라요', '네. 다른 CPU의 데이터 접근도 자동으로 멈춰요'], '정답은 첫 번째예요. 검사 도구의 상태를 바꿔도 다른 실행 흐름의 접근을 막는 잠금이 생기지는 않아요. 오류를 검사하지 않는 것과 오류가 일어나지 않게 보호하는 것은 달라요.')]), 'os1654': ('내 교실에 붙인 안내표가 옆 교실의 규칙까지 바꾸는 것은 아니에요. 한 파일의 검사 설정과 그 파일이 부르는 다른 코드의 설정도 나누어 봐요.', '번역 단위에 따른 중단 별칭과 라이브러리 경계를 이해합니다.', '계측 파일: __kcsan_enable_current → kcsan_enable_current_nowarn, 비계측 파일: 빈 함수로 두 갈래를 그리세요.', ['번역 단위는 컴파일러가 함께 번역하는 코드 덩어리예요. 보통 C 파일 하나와 포함한 헤더를 생각하면 돼요. 라이브러리는 다른 코드에서 불러 쓸 수 있는 함수들을 모은 것이며 별도 파일에서 번역될 수 있어요.', '__SANITIZE_THREAD__ 표시가 있는 번역 단위에서는 __kcsan_disable_current가 kcsan_disable_current에 연결돼요. 별칭은 한 이름을 다른 이름으로 바꾸어 연결하는 규칙이에요.', '같은 조건에서 __kcsan_enable_current는 kcsan_enable_current_nowarn에 연결돼요. 일반 enable 이름과 끝의 nowarn을 구별하세요. 원문은 nowarn 경로를 사용자 메모리 접근 구간에도 사용할 수 있는 경로로 표시해요.', '그 계측 표시가 없으면 __kcsan_disable_current와 __kcsan_enable_current는 둘 다 빈 inline 함수예요. 이 경우 이 두 호출의 본문에는 검사 상태를 바꾸는 일이 없어요. 이름을 호출했다고 언제나 런타임 상태가 바뀌는 것은 아니에요.', '예를 들어 자동 계측을 끈 파일 A가 이 빈 도우미를 부른 뒤 계측된 라이브러리 B를 호출할 수 있어요. A의 도우미가 비어 있으므로 B의 검사까지 꺼졌다고 기대할 수 없어요. 원문도 라이브러리 호출은 여전히 검사할 수 있다고 설명해요.', '따라서 이 별칭은 현재 번역 단위의 접근을 위한 용도로 읽어야 해요. 현재 파일의 표시와 호출 대상의 구현·설정을 함께 확인하세요. 커널 전체 검사를 끄는 버튼이나 작업을 잠들게 하는 schedule 함수가 아니에요.'], [('계측되는 파일에서 __kcsan_enable_current는 어디로 연결되나요?', ['작업을 잠들게 하는 schedule이에요', 'kcsan_enable_current_nowarn이에요'], '정답은 두 번째예요. 원문의 별칭은 nowarn 경로를 지정해요. 여기서는 KCSAN 검사 상태를 다루며 스케줄러로 작업을 잠들게 하는 호출이 아니에요.'), ('이 번역 단위용 별칭을 쓰면 호출하는 모든 라이브러리의 검사까지 반드시 사라지나요?', ['아니요. 라이브러리 호출에서는 여전히 검사할 수 있어요', '네. 커널 전체와 모든 라이브러리의 검사를 꺼요'], '정답은 첫 번째예요. 계측되지 않는 파일에서는 이 별칭 도우미가 빈 함수일 수 있고, 호출한 다른 코드의 검사는 남을 수 있어요. 현재 파일의 조건을 전체 호출 경로의 보장으로 넓히면 안 돼요.')]), 'os1655': ('검사 담당자에게 이 구간은 원자적으로 다뤄지는 접근이라고 표시하는 것과, 실제 문에 자물쇠를 채우는 것은 달라요. 표시는 이미 지켜지는 규칙을 설명하는 역할이에요.', '검사상 atomic 표시의 nestable·flat 상태를 구별합니다.', 'nestable은 0 → 1 → 2 → 1 → 0, flat은 꺼짐 → 켜짐 → 꺼짐으로 그리세요. 두 상태는 독립된 칸이라고 표시하세요.', ['KCSAN atomic 영역은 그 안의 접근을 검사 도구가 원자적으로 간주하도록 알리는 구간이에요. annotation은 이런 검사나 해석을 돕는 표시를 뜻해요. 표시 함수를 불렀다고 일반 읽기·쓰기가 CPU의 원자 명령으로 바뀌지는 않아요.', 'nestable은 안에 또 같은 종류의 구간을 넣을 수 있다는 뜻이에요. nestable_atomic_begin은 atomic_nest_count를 1 늘리고 end는 줄여요. begin 두 번 뒤 end 한 번이면 깊이가 1 남아요.', 'flat은 깊이를 세는 방식이 아니라 상태 하나를 켜고 끄는 방식이에요. flat_atomic_begin은 in_flat_atomic을 true, end는 false로 바꿔요. true는 켜짐, false는 꺼짐이라고 생각할 수 있어요.', 'flat begin을 두 번 불렀다고 깊이가 2로 쌓이지 않아요. end 한 번이면 flat 상태가 꺼져요. 따라서 중첩 횟수를 보존해야 하는 곳에서 flat을 nestable과 똑같이 쓰면 안 돼요.', '원문의 런타임은 nestable 깊이와 flat 상태를 독립적으로 관리해요. 두 종류가 함께 활성화될 수는 있지만 한 종류의 end가 다른 종류의 begin을 대신 정리하지는 않아요. 각 종류에 맞는 시작과 끝을 따라가세요.', '이 표시는 실제 잠금이나 원자적 갱신을 대신하지 않아요. 두 사람이 모두 0을 읽고 각각 1을 쓰는 잘못된 일반 증가에 표시만 붙여도 결과가 자동으로 2가 되지 않아요. 실제 접근의 원자성·순서·수명은 바탕 코드가 충족해야 해요.'], [('nestable atomic 표시를 붙이면 일반 읽기·쓰기가 CPU 원자 RMW로 자동 변하나요?', ['네. 모든 문장을 하나의 원자 작업으로 묶어요', '아니요. KCSAN이 접근을 해석하는 방식을 조절해요'], '정답은 두 번째예요. RMW는 읽기·수정·쓰기이고, 그 원자성을 실제로 제공하는 연산이 필요해요. 검사 표시만으로 일반 명령이 그런 연산으로 바뀌지 않아요.'), ('flat begin/end를 중첩 깊이를 세는 nestable과 같은 방식으로 바꿔 써도 되나요?', ['아니요. flat 상태와 nestable 깊이는 구별해야 해요', '네. 두 API는 이름만 다르고 상태 관리가 같아요'], '정답은 첫 번째예요. nestable은 횟수를 세고 flat은 참·거짓을 저장해요. 둘은 독립적으로 함께 쓰일 수 있어도 서로의 시작과 끝을 대신하는 같은 규칙은 아니에요.')]), 'os1656': ('검사표의 다음 두 항목에 표시하라는 부탁은 종이 두 바이트를 만들라는 뜻도, 뒤의 모든 항목을 바꾸라는 뜻도 아니에요. 숫자가 무엇을 세는지 확인해야 해요.', 'atomic_next의 접근 개수와 검사 해석 범위를 이해합니다.', '검사 도구가 보는 다음 접근 A, B, C를 쓰세요. atomic_next(2)라면 A와 B에 atomic 표시를 하고 C는 이 요청의 범위 밖이라고 적으세요.', ['kcsan_atomic_next(n)은 현재 문맥의 뒤따르는 n번 메모리 접근을 KCSAN이 원자적 접근으로 간주하도록 알리는 함수예요. 현재 문맥은 지금 작업이나 인터럽트 처리처럼 검사가 진행되는 실행 환경이에요.', 'n은 메모리 접근 개수예요. n=1이면 다음 한 접근을 뜻하고 n=2이면 다음 두 접근을 뜻해요. 바이트 수나 CPU 수, 스레드 수를 뜻하는 인자가 아니에요.', '연습에서는 검사 도구가 차례로 보는 접근을 A, B, C라고 놓아 보세요. atomic_next(2) 요청의 대상은 A와 B예요. 소스 한 줄이 반드시 접근 한 번인 것은 아니므로 실제 계측이 보는 접근 단위를 확인해야 해요.', '런타임 함수는 현재 문맥의 atomic_next 칸에 n을 저장해요. 그 설정을 검사 쪽에서 사용하는 것이지 이 함수가 A와 B의 데이터 값을 직접 읽고 쓰는 것은 아니에요. 이후의 모든 실행을 원자적으로 만드는 도구도 아니에요.', '헤더의 ASSERT_EXCLUSIVE_BITS는 선택한 비트에 대한 접근 조건을 검사하고 마스크를 되돌린 뒤 kcsan_atomic_next(1)을 호출해요. 이어지는 한 접근을 낙관적으로 안전하게 취급하려는 표시예요. 마스크는 관심 있는 비트 칸을 고르는 표시예요.', '검사에서 원자적으로 취급한다고 실제 접근이 잠금이나 cmpxchg로 보호되는 것은 아니에요. cmpxchg는 예상 값과 같을 때만 바꾸는 원자 연산이에요. 이런 실제 데이터 보호 규칙과 검사 도구의 분류를 따로 이해해야 해요.'], [('kcsan_atomic_next(1)의 1은 무엇을 세나요?', ['새로 할당할 메모리의 바이트 수예요', '뒤따르는 메모리 접근 개수예요'], '정답은 두 번째예요. 다음 한 접근을 검사에서 원자적으로 간주하라는 뜻이에요. 메모리 길이를 받거나 메모리를 새로 할당하는 함수가 아니에요.'), ('이 호출이 뒤의 모든 접근에 실제 CPU 원자성을 제공하나요?', ['아니요. 정해진 접근에 대한 검사 해석을 조절해요', '네. 스레드 전체가 다른 작업 없이 원자 실행돼요'], '정답은 첫 번째예요. 요청한 개수의 접근을 검사에서 어떻게 볼지 정해요. 다른 실행 흐름을 멈추거나 실제 읽기·쓰기 명령을 원자 연산으로 바꾸지는 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_409.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
